1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.stream.Collectors;
7	import net.officefloor.web.ObjectResponse;
8	
9	/**
10	 * {@code GET /api/clients/outstanding} — how much every client still owes, in one place, so the
11	 * clients list can be ordered by it. For each client it sums the due across ALL of that client's
12	 * invoices (invoice -&gt; project -&gt; client), each invoice's due being its net total after any
13	 * discount/tax (the one-place {@link InvoiceMoney} rule) minus what has been paid against it — the
14	 * same money math as {@link ClientStatementGetLogic}, worked out on the server so every surface
15	 * agrees. Every client gets a row, zero when nothing is owed. Wired by
16	 * {@code officefloor/rest/api/clients/outstanding.GET.yml}.
17	 */
18	public class ClientsOutstandingGetLogic {
19	
20	    public void service(ClientRepository clients, ProjectRepository projects,
21	            InvoiceRepository invoices, PaymentRepository payments,
22	            ObjectResponse<List<ClientOutstandingView>> response) {
23	        // invoice -> project -> client: map each project to the client it belongs to.
24	        Map<Long, Long> projectToClient = projects.findAll().stream()
25	                .collect(Collectors.toMap(Project::getId, Project::getClientId));
26	        List<ClientOutstandingView> rows = clients.findAll().stream()
27	                .map(client -> {
28	                    BigDecimal outstanding = invoices.findAll().stream()
29	                            .filter(i -> client.getId().equals(projectToClient.get(i.getProjectId())))
30	                            .map(i -> {
31	                                BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId())
32	                                        .stream().map(Payment::getAmount)
33	                                        .reduce(BigDecimal.ZERO, BigDecimal::add);
34	                                BigDecimal netTotal = InvoiceMoney.netTotal(i.getAmount(),
35	                                        i.getDiscountPct(), i.getTaxPct());
36	                                return netTotal.subtract(paid);
37	                            })
38	                            .reduce(BigDecimal.ZERO, BigDecimal::add);
39	                    return new ClientOutstandingView(client.getId(), outstanding);
40	                })
41	                .collect(Collectors.toList());
42	        response.send(rows);
43	    }
44	
45	    /** How much one client still owes across all of its invoices. */
46	    public static class ClientOutstandingView {
47	        private final long clientId;
48	        private final BigDecimal outstanding;
49	
50	        public ClientOutstandingView(long clientId, BigDecimal outstanding) {
51	            this.clientId = clientId;
52	            this.outstanding = outstanding;
53	        }
54	
55	        public long getClientId() {
56	            return clientId;
57	        }
58	
59	        public BigDecimal getOutstanding() {
60	            return outstanding;
61	        }
62	    }
63	}
64

