100	                Object primary = contact.get("primary");
101	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role, is_primary)"
102	                        + " VALUES (?, ?, ?, ?, ?, ?)",
103	                        ((Number) contact.get("id")).longValue(),
104	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
