197	                        ((Number) invoice.get("projectId")).longValue(),
198	                        amount,
199	                        status != null ? status.toString() : "UNPAID",
200	                        issuedDate != null ? java.sql.Date.valueOf(issuedDate.toString()) : null,
201	                        dueDate != null ? java.sql.Date.valueOf(dueDate.toString()) : null,
202	                        discountPct != null ? new java.math.BigDecimal(discountPct.toString())
203	                                : java.math.BigDecimal.ZERO,
204	                        taxPct != null ? new java.math.BigDecimal(taxPct.toString())
205	                                : java.math.BigDecimal.ZERO);
206	                if (lineItems != null) {
207	                    for (Map<String, Object> line : lineItems) {
208	                        // unit is optional in a fixture; default to "units" (matching Flyway V26).
209	                        Object unit = line.get("unit");
210	                        jdbc.update("INSERT INTO invoice_line_items"
211	                                + " (id, invoice_id, description, qty, unit, unit_price)"
212	                                + " VALUES (?, ?, ?, ?, ?, ?)",
213	                                ((Number) line.get("id")).longValue(), invoiceId,
214	                                line.get("description"), ((Number) line.get("qty")).intValue(),
215	                                unit != null ? unit.toString() : "units",
216	                                new java.math.BigDecimal(line.get("unitPrice").toString()));
217	                    }
218	                }
219	            }
220	        }
221	        List<Map<String, Object>> payments = (List<Map<String, Object>>) fixture.get("payments");
222	        if (payments != null) {
223	            long maxId = 0;
224	            for (Map<String, Object> payment : payments) {
225	                long id = ((Number) payment.get("id")).longValue();
226	                maxId = Math.max(maxId, id);
227	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
228	                jdbc.update("INSERT INTO payments (id, invoice_id, amount, paid_date)"
229	                        + " VALUES (?, ?, ?, ?)",
230	                        id,
231	                        ((Number) payment.get("invoiceId")).longValue(),
232	                        new java.math.BigDecimal(payment.get("amount").toString()),
233	                        java.sql.Date.valueOf(payment.get("date").toString()));
234	            }
235	            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
236	            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
237	            if (maxId > 0) {
238	                jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + (maxId + 1));
239	            }
240	        }
241	    }
242	
243	    /**
244	     * Parse a fixture's `at` value to an instant. A full ISO instant ("2026-01-05T09:00:00Z") is
245	     * used as-is; a date-only value ("2026-02-01") is taken at the start of that day in UTC, so a
246	     * spec can stamp a note with just a date.
247	     */
248	    private static java.time.Instant parseInstant(String at) {
249	        try {
250	            return java.time.Instant.parse(at);
251	        } catch (java.time.format.DateTimeParseException dateOnly) {
252	            return java.time.LocalDate.parse(at)
253	                    .atStartOfDay(java.time.ZoneOffset.UTC).toInstant();
254	        }
255	    }
256	}
